def strip_line(line):
    res = []
    i, n = 0, len(line)
    in_str = in_char = False
    while i < n:
        c = line[i]
        if in_str:
            if c == '\\' and i + 1 < n:
                res.append(line[i:i+2]); i += 2; continue
            if c == '"': in_str = False
            res.append(c); i += 1; continue
        if in_char:
            if c == '\\' and i + 1 < n:
                res.append(line[i:i+2]); i += 2; continue
            if c == "'": in_char = False
            res.append(c); i += 1; continue
        if c == '"':
            in_str = True; res.append(c); i += 1; continue
        if c == "'":
            in_char = True; res.append(c); i += 1; continue
        if c == '/' and i + 1 < n and line[i+1] == '/':
            break
        res.append(c); i += 1
    if in_str or in_char:
        raise ValueError("unterminated literal: " + line)
    return ''.join(res)

with open(path) as f:
    lines = f.read().split('\n')

out = []
removed = 0
for line in lines:
    stripped = strip_line(line)
    if line.strip() and not stripped.strip():
        removed += 1
        continue
    out.append(stripped.rstrip() if stripped != line else line)

with open(path, 'w') as f:
    f.write('\n'.join(out))
print(f"removed {removed} comment-only lines")
EOF

