import glob, struct, collections
def chunks(path):
    d = open(path,'rb').read()
    i=8; out=[]
    while i < len(d):
        ln = struct.unpack('>I', d[i:i+4])[0]
        typ = d[i+4:i+8].decode('latin1')
        out.append((typ, ln)); i += 12+ln
    return tuple(out)
sig = collections.defaultdict(list)
for f in sorted(glob.glob('textures/*.png')):
    sig[chunks(f)].append(f.split('/')[-1])
for k,v in sig.items():
    print(len(v), [f"{t}:{n}" for t,n in k][:12], '...')
    for f in v[:2]: print('   ', f)
